-- Migration 036: 50 more real, local Georgia organizations across a broad mix of
-- categories (food, animals, music, tech, faith, disaster, environment, seniors,
-- education, gardening, community, medicine, sports, veterans) and cities beyond
-- Atlanta (Savannah, Augusta, Columbus, Macon, Athens, Gainesville, Roswell,
-- Marietta, Decatur, and more). Each org was researched individually and its
-- website/volunteer page verified. Pure inserts with fixed ids - safe to re-run,
-- existing rows untouched. Complements migration-008 (the first 24 GA orgs).

insert into public.organizations
  (id, owner_id, name, description, website, logo_url, category, tags, remote, international,
   min_age, country, state, city, verified, counts_for_service_hours, commitment_type, featured)
values
  -- FOOD
  -- NOTE: 'Atlanta Community Food Bank' (was c1...001) removed - it duplicated an
  -- existing directory org (e5...024); see migration-042-dedupe-036.sql.
  ('c1000000-0000-4000-8000-000000000002', null, 'Second Helpings Atlanta', 'A food-rescue nonprofit whose volunteers use their own vehicles to pick up surplus fresh food from grocers and restaurants and deliver it to shelters, pantries, and after-school programs across metro Atlanta.', 'https://secondhelpingsatlanta.org', 'https://www.google.com/s2/favicons?domain=secondhelpingsatlanta.org&sz=128', 'food', array['good for crews', 'recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000003', null, 'Open Hand Atlanta', 'A nonprofit that cooks and delivers medically tailored meals to seniors and people managing chronic illness across metro Atlanta, relying on volunteers in the kitchen and on delivery routes.', 'https://www.openhandatlanta.org', 'https://www.google.com/s2/favicons?domain=www.openhandatlanta.org&sz=128', 'food', array['recurring', 'good for crews'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000004', null, 'Golden Harvest Food Bank', 'The regional food bank for the Augusta area and the Central Savannah River region, distributing millions of meals a year through a network of pantries and a Master''s Table soup kitchen.', 'https://www.goldenharvest.org', 'https://www.google.com/s2/favicons?domain=www.goldenharvest.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 12, 'United States', 'GA', 'Augusta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000005', null, 'Feeding the Valley Food Bank', 'The food bank serving Columbus and the Chattahoochee Valley region of west Georgia, receiving and distributing donated food and fresh produce to partner agencies across many counties.', 'https://feedingthevalley.org', 'https://www.google.com/s2/favicons?domain=feedingthevalley.org&sz=128', 'food', array['good for crews', 'physical work'], false, false, 12, 'United States', 'GA', 'Columbus', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000006', null, 'Georgia Mountain Food Bank', 'A food bank in Gainesville serving Hall, Dawson, Forsyth, Lumpkin, and Union counties in north Georgia, distributing food to partner agencies and running a community garden.', 'https://www.gamountainfoodbank.org', 'https://www.google.com/s2/favicons?domain=www.gamountainfoodbank.org&sz=128', 'food', array['good for crews', 'family friendly'], false, false, 12, 'United States', 'GA', 'Gainesville', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000007', null, 'Urban Recipe', 'An Atlanta nonprofit built around food co-ops, where neighbors work together to pack and distribute roughly 40,000 pounds of groceries a month with dignity rather than a traditional pantry line.', 'https://urbanrecipe.org', 'https://www.google.com/s2/favicons?domain=urbanrecipe.org&sz=128', 'food', array['recurring', 'good for crews'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- ANIMALS
  ('c1000000-0000-4000-8000-000000000008', null, 'Atlanta Humane Society', 'One of the oldest and largest animal-welfare organizations in Georgia, caring for and rehoming thousands of dogs and cats each year across its metro Atlanta campuses.', 'https://atlantahumane.org', 'https://www.google.com/s2/favicons?domain=atlantahumane.org&sz=128', 'animals', array['recurring'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- NOTE: 'LifeLine Animal Project' (was c1...009) removed - it duplicated an
  -- existing directory org (e5...025); see migration-042-dedupe-036.sql.
  ('c1000000-0000-4000-8000-000000000010', null, 'Furkids', 'Georgia''s largest no-kill animal rescue and shelter organization, operating cat and dog shelters in metro Atlanta and welcoming youth volunteers alongside a parent for cat care and puppy socialization.', 'https://furkids.org', 'https://www.google.com/s2/favicons?domain=furkids.org&sz=128', 'animals', array['family friendly', 'recurring'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000011', null, 'PAWS Atlanta', 'One of metro Atlanta''s oldest no-kill shelters, based in Decatur, caring for homeless dogs and cats and relying on adult volunteers for daily animal care and events.', 'https://www.pawsatlanta.org', 'https://www.google.com/s2/favicons?domain=www.pawsatlanta.org&sz=128', 'animals', array['recurring'], false, false, 18, 'United States', 'GA', 'Decatur', true, true, 'ongoing', false),
  ('c1000000-0000-4000-8000-000000000012', null, 'Humane Society for Greater Savannah', 'A nonprofit shelter serving the Savannah area with adoption, foster, and community programs, offering hands-on and event volunteer roles for a range of ages.', 'https://www.humanesocietysav.org', 'https://www.google.com/s2/favicons?domain=www.humanesocietysav.org&sz=128', 'animals', array['recurring', 'family friendly'], false, false, 14, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000013', null, 'AWARE Wildlife Center', 'A wildlife rehabilitation center on the edge of Atlanta''s Arabia Mountain that rescues, treats, and releases native Georgia wildlife and trains volunteers in animal care and habitat work.', 'https://awarewildlife.org', 'https://www.google.com/s2/favicons?domain=awarewildlife.org&sz=128', 'animals', array['outdoors', 'recurring'], false, false, 16, 'United States', 'GA', 'Lithonia', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000014', null, 'Coastal Pet Rescue', 'A Savannah-area rescue that finds homes for dogs and cats through a foster-based network and welcomes volunteers, including teens with parental permission through its CPR Teens program.', 'https://coastalpetrescue.org', 'https://www.google.com/s2/favicons?domain=coastalpetrescue.org&sz=128', 'animals', array['recurring', 'family friendly'], false, false, 14, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  -- MUSIC
  ('c1000000-0000-4000-8000-000000000015', null, 'Atlanta Music Project', 'A nonprofit that provides intensive, tuition-free music education and performance training to young people in under-resourced Atlanta communities.', 'https://atlantamusicproject.org', 'https://www.google.com/s2/favicons?domain=atlantamusicproject.org&sz=128', 'music', array['recurring', 'creative work'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000016', null, 'Pianos for Peace', 'An Atlanta nonprofit that builds peace through music and education, placing painted street pianos around the city and delivering arts programs to schools, hospitals, and senior homes.', 'https://www.pianosforpeace.org', 'https://www.google.com/s2/favicons?domain=www.pianosforpeace.org&sz=128', 'music', array['creative work', 'good for crews'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000017', null, 'Henry For Music', 'A metro Atlanta 501(c)(3) that collects and gifts tuition-free instruments and music lessons to students who have the interest but not the means, powered by volunteer mentors and artists.', 'https://henryformusic.org', 'https://www.google.com/s2/favicons?domain=henryformusic.org&sz=128', 'music', array['creative work', 'recurring'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- TECH
  ('c1000000-0000-4000-8000-000000000018', null, 'TechBridge', 'An Atlanta nonprofit that brings affordable technology and business expertise to other nonprofits and runs a free technology career training program to help break the cycle of poverty.', 'https://techbridge.org', 'https://www.google.com/s2/favicons?domain=techbridge.org&sz=128', 'tech', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000019', null, 'Bridge2Tech', 'A Georgia nonprofit offering free STEM, coding, and esports programs to at-risk and underserved youth, with volunteer roles mentoring students in technology skills.', 'https://www.bridge2tech.org', 'https://www.google.com/s2/favicons?domain=www.bridge2tech.org&sz=128', 'tech', array['recurring', 'leadership role', 'counts for school hours'], false, false, 13, 'United States', 'GA', 'Roswell', true, true, 'both', false),
  -- FAITH
  ('c1000000-0000-4000-8000-000000000020', null, 'Atlanta Habitat for Humanity', 'A Christian housing ministry that partners with families to build and repair affordable homes across Atlanta, engaging over 6,000 volunteers a year on build sites and in its ReStore.', 'https://atlantahabitat.org', 'https://www.google.com/s2/favicons?domain=atlantahabitat.org&sz=128', 'faith', array['good for crews', 'physical work', 'outdoors'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000021', null, 'Augusta Habitat for Humanity', 'A volunteer-driven affiliate of Habitat for Humanity serving the Augusta and CSRA region, building and rehabbing homes with skilled and unskilled volunteers alike.', 'https://augustahabitat.org', 'https://www.google.com/s2/favicons?domain=augustahabitat.org&sz=128', 'faith', array['good for crews', 'physical work', 'outdoors'], false, false, 16, 'United States', 'GA', 'Augusta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000022', null, 'Catholic Charities Atlanta', 'A faith-based social services agency serving people of all backgrounds across north Georgia with refugee resettlement, counseling, and family support programs, plus tutoring and mentoring volunteer roles.', 'https://catholiccharitiesatlanta.org', 'https://www.google.com/s2/favicons?domain=catholiccharitiesatlanta.org&sz=128', 'faith', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000023', null, 'MUST Ministries', 'A faith-based nonprofit in Marietta serving people facing hunger and homelessness across Cobb, Cherokee, and surrounding counties through shelters, food pantries, and a summer lunch program for kids.', 'https://www.mustministries.org', 'https://www.google.com/s2/favicons?domain=www.mustministries.org&sz=128', 'faith', array['good for crews', 'family friendly', 'recurring'], false, false, 13, 'United States', 'GA', 'Marietta', true, true, 'both', false),
  -- DISASTER RELIEF
  ('c1000000-0000-4000-8000-000000000024', null, 'American Red Cross of Georgia', 'The Georgia region of the American Red Cross, where trained volunteers respond to home fires and larger disasters with food, shelter, and comfort and can deploy statewide or nationally.', 'https://www.redcross.org/local/georgia.html', 'https://www.google.com/s2/favicons?domain=www.redcross.org&sz=128', 'disaster', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- ENVIRONMENT
  ('c1000000-0000-4000-8000-000000000025', null, 'Savannah Riverkeeper', 'A nonprofit advocacy organization protecting the Savannah River watershed through restoration, education, and dozens of river and community cleanups a year in Augusta, Savannah, and between.', 'https://www.savannahriverkeeper.org', 'https://www.google.com/s2/favicons?domain=www.savannahriverkeeper.org&sz=128', 'environment', array['outdoors', 'physical work', 'good for crews'], false, false, 12, 'United States', 'GA', 'Augusta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000026', null, 'Ogeechee Riverkeeper', 'A coastal Georgia nonprofit defending the Ogeechee, Canoochee, and coastal watersheds through water-quality monitoring, litter cleanups, and its Protect the Vernon project.', 'https://www.ogeecheeriverkeeper.org', 'https://www.google.com/s2/favicons?domain=www.ogeecheeriverkeeper.org&sz=128', 'environment', array['outdoors', 'physical work', 'good for crews'], false, false, 12, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000027', null, 'Chattahoochee Riverkeeper', 'One of the country''s most effective river-protection groups, guarding the Chattahoochee - metro Atlanta''s main drinking-water source - through cleanups, water testing, and advocacy.', 'https://chattahoochee.org', 'https://www.google.com/s2/favicons?domain=chattahoochee.org&sz=128', 'environment', array['outdoors', 'physical work', 'good for crews'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000028', null, 'Chattahoochee Nature Center', 'A nonprofit nature center in Roswell along the Chattahoochee River offering wildlife, gardening, and education volunteer roles for teens and adults amid 127 acres of protected land.', 'https://www.chattnaturecenter.org', 'https://www.google.com/s2/favicons?domain=www.chattnaturecenter.org&sz=128', 'environment', array['outdoors', 'recurring', 'family friendly'], false, false, 12, 'United States', 'GA', 'Roswell', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000029', null, 'Georgia Adopt-A-Stream', 'A statewide program that trains volunteers to adopt and monitor a local stream, river, lake, or wetland, collecting real water-quality data that protects Georgia''s waterways.', 'https://adoptastream.georgia.gov', 'https://www.google.com/s2/favicons?domain=adoptastream.georgia.gov&sz=128', 'environment', array['outdoors', 'recurring', 'counts for school hours'], false, false, 12, 'United States', 'GA', 'Georgia', true, true, 'both', false),
  -- SENIORS
  ('c1000000-0000-4000-8000-000000000030', null, 'Senior Citizens Inc.', 'A Savannah nonprofit that has run Meals on Wheels of Coastal Georgia for decades, delivering meals and daily check-ins to homebound older adults across seven coastal counties.', 'https://seniorcitizensinc.org', 'https://www.google.com/s2/favicons?domain=seniorcitizensinc.org&sz=128', 'seniors', array['recurring'], false, false, 16, 'United States', 'GA', 'Savannah', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000031', null, 'Meals on Wheels of Middle Georgia', 'A nonprofit delivering hot meals and friendly visits to homebound seniors around Macon and middle Georgia, pairing nutrition with a daily safety check.', 'https://www.mowmidga.org', 'https://www.google.com/s2/favicons?domain=www.mowmidga.org&sz=128', 'seniors', array['recurring'], false, false, 16, 'United States', 'GA', 'Macon', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000032', null, 'Athens Community Council on Aging', 'An Athens nonprofit supporting older adults with meals, day programs, a community garden, and companionship, offering volunteer roles from meal delivery to garden work.', 'https://www.accaging.org', 'https://www.google.com/s2/favicons?domain=www.accaging.org&sz=128', 'seniors', array['recurring', 'outdoors'], false, false, 14, 'United States', 'GA', 'Athens', true, true, 'both', false),
  -- EDUCATION
  ('c1000000-0000-4000-8000-000000000033', null, 'Communities In Schools of Atlanta', 'The Atlanta affiliate of the nation''s largest dropout-prevention network, surrounding students with support through mentoring, reading coaching, and lunch-buddy programs inside schools.', 'https://www.cisatlanta.org', 'https://www.google.com/s2/favicons?domain=www.cisatlanta.org&sz=128', 'education', array['recurring', 'counts for school hours', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000034', null, 'Horizons Atlanta', 'A nonprofit running six-week summer learning programs for students from under-resourced communities, closing the summer learning gap with the help of volunteer readers and classroom helpers.', 'https://horizonsatlanta.org', 'https://www.google.com/s2/favicons?domain=horizonsatlanta.org&sz=128', 'education', array['recurring', 'counts for school hours'], false, false, 14, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000035', null, 'Junior Achievement of Georgia', 'A nonprofit that sends volunteers into classrooms across Georgia to teach students about work readiness, entrepreneurship, and financial literacy through hands-on lessons.', 'https://www.georgia.ja.org', 'https://www.google.com/s2/favicons?domain=www.georgia.ja.org&sz=128', 'education', array['leadership role', 'counts for school hours'], false, false, 18, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000036', null, 'SAV Youth Mentoring Hub', 'A Savannah initiative that connects the community with vetted local youth-mentoring organizations, making it easy to find and apply to become a mentor to a young person.', 'https://savyouthmentoring.org', 'https://www.google.com/s2/favicons?domain=savyouthmentoring.org&sz=128', 'education', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Savannah', true, true, 'ongoing', false),
  -- GARDENING
  ('c1000000-0000-4000-8000-000000000037', null, 'Athens Land Trust', 'An Athens nonprofit protecting land and building community through affordable housing and community agriculture, including the West Broad Market Garden and a Young Urban Farmers program.', 'https://athenslandtrust.org', 'https://www.google.com/s2/favicons?domain=athenslandtrust.org&sz=128', 'gardening', array['outdoors', 'physical work', 'good for crews'], false, false, 14, 'United States', 'GA', 'Athens', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000038', null, 'The Metro Atlanta Urban Farm', 'A working urban farm in the College Park area that grows fresh produce to fight food insecurity and teaches sustainable agriculture, welcoming volunteers and groups for farm workdays.', 'https://themetroatlantaurbanfarm.org', 'https://www.google.com/s2/favicons?domain=themetroatlantaurbanfarm.org&sz=128', 'gardening', array['outdoors', 'physical work', 'family friendly'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000039', null, 'Concrete Jungle', 'An Atlanta and Athens nonprofit whose volunteers glean fruit from urban trees and harvest at partner farms, distributing fresh produce to soup kitchens and food pantries.', 'https://concrete-jungle.org', 'https://www.google.com/s2/favicons?domain=concrete-jungle.org&sz=128', 'gardening', array['outdoors', 'physical work', 'good for crews'], false, false, 12, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- COMMUNITY
  ('c1000000-0000-4000-8000-000000000040', null, 'North Fulton Community Charities', 'A Roswell nonprofit preventing homelessness and hunger in north Fulton with a food pantry, thrift store, and financial assistance, staffed largely by volunteers.', 'https://nfcchelp.org', 'https://www.google.com/s2/favicons?domain=nfcchelp.org&sz=128', 'community', array['recurring', 'good for crews', 'family friendly'], false, false, 13, 'United States', 'GA', 'Roswell', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000041', null, 'The Backpack Project', 'A student-run nonprofit that packs and hand-delivers backpacks of food, toiletries, and essentials to people experiencing homelessness, with chapters serving Athens, Atlanta, and Augusta.', 'https://www.thebackpackproject.ngo', 'https://www.google.com/s2/favicons?domain=www.thebackpackproject.ngo&sz=128', 'community', array['good for crews', 'counts for school hours', 'family friendly'], false, false, 14, 'United States', 'GA', 'Athens', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000042', null, 'Goodwill of North Georgia', 'A nonprofit that turns donated goods into job training and career services, helping tens of thousands of Georgians each year find work through its career centers.', 'https://goodwillng.org', 'https://www.google.com/s2/favicons?domain=goodwillng.org&sz=128', 'community', array['recurring', 'good for crews'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000043', null, 'Hands On Atlanta', 'A volunteer hub that matches individuals, families, and groups with hundreds of service projects at nonprofits and schools across metro Atlanta, making it easy to find a first project.', 'https://www.handsonatlanta.org', 'https://www.google.com/s2/favicons?domain=www.handsonatlanta.org&sz=128', 'community', array['good for crews', 'family friendly', 'recurring'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- MEDICINE
  ('c1000000-0000-4000-8000-000000000044', null, 'Ronald McDonald House Charities of Atlanta', 'A nonprofit providing a home away from home for families whose children are being treated at Atlanta hospitals, with volunteer roles cooking meals and welcoming families.', 'https://ronaldmcdonaldhouseatl.org', 'https://www.google.com/s2/favicons?domain=ronaldmcdonaldhouseatl.org&sz=128', 'medicine', array['recurring', 'family friendly', 'good for crews'], false, false, 13, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000045', null, 'Ronald McDonald House Charities of Central Georgia', 'The Macon-based Ronald McDonald House supporting families of hospitalized children in central Georgia, relying on volunteers for meals, housekeeping, and front-desk help.', 'https://www.rmhccga.org', 'https://www.google.com/s2/favicons?domain=www.rmhccga.org&sz=128', 'medicine', array['recurring', 'good for crews'], false, false, 16, 'United States', 'GA', 'Macon', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000046', null, 'Shepherd Center', 'A nationally ranked Atlanta hospital specializing in spinal cord and brain injury rehabilitation, with a large volunteer program supporting patients, families, and recreation therapy.', 'https://www.shepherd.org', 'https://www.google.com/s2/favicons?domain=www.shepherd.org&sz=128', 'medicine', array['recurring', 'counts for school hours'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- SPORTS
  ('c1000000-0000-4000-8000-000000000047', null, 'BlazeSports America', 'An Atlanta-based nonprofit and legacy of the 1996 Paralympic Games that provides adaptive sports and recreation for children and adults with physical disabilities.', 'https://blazesports.org', 'https://www.google.com/s2/favicons?domain=blazesports.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 14, 'United States', 'GA', 'Decatur', true, true, 'both', false),
  ('c1000000-0000-4000-8000-000000000048', null, 'Soccer in the Streets', 'An Atlanta nonprofit using soccer to develop youth in under-resourced neighborhoods, famous for its StationSoccer fields built at MARTA transit stations.', 'https://www.soccerstreets.org', 'https://www.google.com/s2/favicons?domain=www.soccerstreets.org&sz=128', 'sports', array['recurring', 'leadership role'], false, false, 16, 'United States', 'GA', 'Atlanta', true, true, 'both', false),
  -- VETERANS
  ('c1000000-0000-4000-8000-000000000049', null, 'Middle Georgia Honor Flight', 'A nonprofit that flies World War II, Korea, and Vietnam-era veterans to Washington, D.C. at no cost to visit their memorials, pairing each veteran with a volunteer Guardian.', 'https://www.middlegahonorflight.org', 'https://www.google.com/s2/favicons?domain=www.middlegahonorflight.org&sz=128', 'veterans', array['leadership role', 'good for crews'], false, false, 16, 'United States', 'GA', 'Warner Robins', true, true, 'one-time', false),
  ('c1000000-0000-4000-8000-000000000050', null, 'Coastal Georgia Honor Flight', 'A Savannah-area nonprofit honoring coastal Georgia veterans with all-expenses-paid trips to see their memorials in Washington, D.C., supported by volunteers and Guardians.', 'https://coastalgeorgiahonorflight.org', 'https://www.google.com/s2/favicons?domain=coastalgeorgiahonorflight.org&sz=128', 'veterans', array['leadership role', 'good for crews'], false, false, 16, 'United States', 'GA', 'Savannah', true, true, 'one-time', false)
